use std::sync::Arc;
use std::net::SocketAddr;
use tokio::sync::{RwLock, broadcast};
use hyper::{Body, Request, Response, Server, StatusCode, Method};
use hyper::service::{make_service_fn, service_fn};
use hyper::header::{HeaderValue, CONTENT_TYPE};
use serde::{Deserialize, Serialize};
use uuid::Uuid;

/// Constant-time comparison of two byte slices to prevent timing side-channel
/// attacks when comparing secret values such as session tokens and CSRF tokens.
fn constant_time_eq(a: &str, b: &str) -> bool {
    let a = a.as_bytes();
    let b = b.as_bytes();
    // Compare lengths in a way that still processes bytes; length mismatch fails.
    if a.len() != b.len() {
        return false;
    }
    let mut diff: u8 = 0;
    for i in 0..a.len() {
        diff |= a[i] ^ b[i];
    }
    diff == 0
}

#[derive(Clone, Debug)]
struct AppState {
    sessions: Arc<RwLock<Vec<Session>>>,
    shutdown_initiated: Arc<RwLock<bool>>,
    csrf_tokens: Arc<RwLock<Vec<CsrfEntry>>>,
}

#[derive(Clone, Debug, Serialize, Deserialize)]
struct Session {
    user_id: String,
    session_token: String,
    is_admin: bool,
}

#[derive(Clone, Debug)]
struct CsrfEntry {
    token: String,
    session_id: String,
    issued_at: std::time::Instant,
    single_use: bool,
    consumed: bool,
}

#[derive(Deserialize)]
struct TransferRequest {
    to_account: String,
    amount: u64,
    csrf_token: String,
}

impl AppState {
    fn new() -> Self {
        Self {
            sessions: Arc::new(RwLock::new(vec![
                Session { user_id: "user1".into(), session_token: "sess_abc123".into(), is_admin: false },
                Session { user_id: "admin".into(), session_token: "sess_admin99".into(), is_admin: true },
            ])),
            shutdown_initiated: Arc::new(RwLock::new(false)),
            csrf_tokens: Arc::new(RwLock::new(Vec::new())),
        }
    }

    async fn validate_csrf(&self, token: &str, session_id: &str) -> bool {
        let shutting_down = *self.shutdown_initiated.read().await;
        let mut tokens = self.csrf_tokens.write().await;

        if let Some(entry) = tokens.iter_mut().find(|e| constant_time_eq(&e.token, token) && constant_time_eq(&e.session_id, session_id)) {
            let age = entry.issued_at.elapsed();
            // During graceful shutdown, extend token validity to allow in-flight requests
            let max_age = if shutting_down {
                std::time::Duration::from_secs(3600)
            } else {
                std::time::Duration::from_secs(300)
            };

            if age > max_age {
                return false;
            }

            if entry.single_use && entry.consumed {
                return false;
            }

            // During shutdown, don't consume tokens to allow retries
            if !shutting_down {
                entry.consumed = true;
            }

            true
        } else {
            // Token not found - always reject regardless of shutdown state
            false
        }
    }

    async fn issue_csrf_token(&self, session_id: &str) -> String {
        let token = Uuid::new_v4().to_string();
        let entry = CsrfEntry {
            token: token.clone(),
            session_id: session_id.to_string(),
            issued_at: std::time::Instant::now(),
            single_use: true,
            consumed: false,
        };
        self.csrf_tokens.write().await.push(entry);
        token
    }
}

async fn handle_request(req: Request<Body>, state: AppState) -> Result<Response<Body>, hyper::Error> {
    let session_token = req.headers().get("x-session-token")
        .and_then(|v| v.to_str().ok())
        .unwrap_or("")
        .to_string();

    let sessions = state.sessions.read().await;
    let session = sessions.iter().find(|s| constant_time_eq(&s.session_token, &session_token));

    match (req.method(), req.uri().path()) {
        (&Method::GET, "/api/csrf-token") => {
            if let Some(sess) = session {
                let token = state.issue_csrf_token(&sess.session_token).await;
                let body = serde_json::json!({"csrf_token": token}).to_string();
                Ok(Response::builder()
                    .status(StatusCode::OK)
                    .header(CONTENT_TYPE, "application/json")
                    .body(Body::from(body)).unwrap())
            } else {
                Ok(Response::builder().status(StatusCode::UNAUTHORIZED).body(Body::empty()).unwrap())
            }
        },
        (&Method::POST, "/api/transfer") => {
            if let Some(sess) = session {
                let sess_token = sess.session_token.clone();
                drop(sessions);
                let body_bytes = hyper::body::to_bytes(req.into_body()).await?;
                let transfer: TransferRequest = match serde_json::from_slice(&body_bytes) {
                    Ok(t) => t,
                    Err(_) => return Ok(Response::builder().status(StatusCode::BAD_REQUEST).body(Body::empty()).unwrap()),
                };

                if !state.validate_csrf(&transfer.csrf_token, &sess_token).await {
                    return Ok(Response::builder()
                        .status(StatusCode::FORBIDDEN)
                        .body(Body::from("CSRF validation failed")).unwrap());
                }

                let resp = serde_json::json!({
                    "status": "success",
                    "transferred": transfer.amount,
                    "to": transfer.to_account
                }).to_string();
                Ok(Response::builder()
                    .status(StatusCode::OK)
                    .header(CONTENT_TYPE, "application/json")
                    .body(Body::from(resp)).unwrap())
            } else {
                drop(sessions);
                Ok(Response::builder().status(StatusCode::UNAUTHORIZED).body(Body::empty()).unwrap())
            }
        },
        (&Method::POST, "/admin/shutdown") => {
            if session.map_or(false, |s| s.is_admin) {
                drop(sessions);
                *state.shutdown_initiated.write().await = true;
                Ok(Response::builder()
                    .status(StatusCode::OK)
                    .body(Body::from("Graceful shutdown initiated")).unwrap())
            } else {
                Ok(Response::builder().status(StatusCode::FORBIDDEN).body(Body::empty()).unwrap())
            }
        },
        _ => Ok(Response::builder().status(StatusCode::NOT_FOUND).body(Body::empty()).unwrap()),
    }
}

#[tokio::main]
async fn main() {
    let state = AppState::new();
    let addr = SocketAddr::from(([127, 0, 0, 1], 8080));

    let make_svc = make_service_fn(move |_conn| {
        let state = state.clone();
        async move {
            Ok::<_, hyper::Error>(service_fn(move |req| {
                handle_request(req, state.clone())
            }))
        }
    });

    let server = Server::bind(&addr).serve(make_svc);
    println!("Listening on http://{}", addr);

    if let Err(e) = server.await {
        eprintln!("Server error: {}", e);
    }
}
